### C++

```cpp
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

// 将十进制字符串大数转换为二进制字符串
string decToBinary(string n) {
    if (n == "0") return "0";
    string binary = "";
    while (n != "0") {
        int carry = 0;
        string temp;
        // 逐位除以2
        for (char c : n) {
            int cur = carry * 10 + (c - '0');
            temp.push_back((cur / 2) + '0');
            carry = cur % 2;
        }
        // 当前余数即为二进制的一位
        binary.push_back(carry + '0');
        // 去除前导零
        size_t pos = temp.find_first_not_of('0');
        n = (pos == string::npos) ? "0" : temp.substr(pos);
    }
    // 倒序得到正确的二进制表示
    reverse(binary.begin(), binary.end());
    return binary;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    int k;
    cin >> n >> k;

    string binaryN = decToBinary(n);
    // 乘以 2^k 等价于末尾追加 k 个 '0'
    binaryN.append(k, '0');

    cout << binaryN << "\n";
    return 0;
}
